<script>
(function(){
  "use strict";

  // ---------- Config ----------
  const COLS = 20, ROWS = 20;
  const BASE_MS = 150;      // starting step interval
  const MIN_MS  = 65;       // fastest
  const SPEEDUP = 3;        // ms faster per food
  const POINTS  = 10;

  // ---------- DOM ----------
  const canvas   = document.getElementById('game');
  const ctx      = canvas.getContext('2d');
  const scoreEl  = document.getElementById('score');
  const bestEl   = document.getElementById('best');
  const lenEl    = document.getElementById('len');
  const speedEl  = document.getElementById('speed');
  const startBtn = document.getElementById('startBtn');
  const startLabel = document.getElementById('startLabel');
  const restartBtn = document.getElementById('restartBtn');
  const overlay  = document.getElementById('overlay');
  const ovTag    = document.getElementById('ovTag');
  const ovTitle  = document.getElementById('ovTitle');
  const ovSub    = document.getElementById('ovSub');
  const ovBtn    = document.getElementById('ovBtn');
  const newBest  = document.getElementById('newBest');
  const dpad     = document.getElementById('dpad');
  const dpadCenter = document.getElementById('dpadCenter');

  // ---------- State ----------
  let cell = 24, dpr = 1;
  let snake, dir, nextDir, food, score, best, stepMs, acc, last;
  let state = 'ready';       // ready | running | paused | over
  let particles = [];
  let foodPulse = 0;
  let shake = 0;

  best = parseInt(localStorage.getItem('snake_best') || '0', 10) || 0;
  bestEl.textContent = best;

  // ---------- Canvas sizing ----------
  function resize(){
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    const size = Math.max(1, Math.floor(rect.width));
    canvas.width  = size * dpr;
    canvas.height = size * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    cell = size / COLS;
  }
  window.addEventListener('resize', resize);

  // ---------- Helpers ----------
  const key = (x,y) => x + ',' + y;
  function randFood(){
    let x, y, tries = 0;
    do {
      x = Math.floor(Math.random()*COLS);
      y = Math.floor(Math.random()*ROWS);
      tries++;
    } while (snake.some(s => s.x===x && s.y===y) && tries < 500);
    return {x, y};
  }
  function reset(){
    const cx = Math.floor(COLS/2), cy = Math.floor(ROWS/2);
    snake = [{x:cx-1,y:cy},{x:cx,y:cy},{x:cx+1,y:cy}];
    dir = {x:1,y:0};
    nextDir = {x:1,y:0};
    score = 0;
    stepMs = BASE_MS;
    acc = 0;
    particles = [];
    food = randFood();
    updateHud();
  }

  // ---------- HUD ----------
  function updateHud(){
    scoreEl.textContent = score;
    lenEl.textContent = snake.length;
    const mult = (BASE_MS / stepMs).toFixed(1);
    speedEl.textContent = mult + '×';
  }
  function bumpScore(){
    scoreEl.classList.remove('bump');
    void scoreEl.offsetWidth;
    scoreEl.classList.add('bump');
  }

  // ---------- Particles ----------
  function spawnBurst(px, py, color){
    for (let i=0;i<16;i++){
      const a = Math.random()*Math.PI*2;
      const sp = 40 + Math.random()*120;
      particles.push({
        x:px, y:py,
        vx:Math.cos(a)*sp, vy:Math.sin(a)*sp,
        life:1, size:2+Math.random()*3, color
      });
    }
  }
  function updateParticles(dt){
    for (let i=particles.length-1;i>=0;i--){
      const p = particles[i];
      p.x += p.vx*dt; p.y += p.vy*dt;
      p.vx *= 0.94; p.vy *= 0.94;
      p.life -= dt*1.8;
      if (p.life <= 0) particles.splice(i,1);
    }
  }

  // ---------- Game step ----------
  function step(){
    dir = nextDir;
    const head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};

    // wall collision
    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS){
      gameOver(); return;
    }
    // self collision (tail cell will move unless we eat)
    const willEat = (head.x === food.x && head.y === food.y);
    const body = willEat ? snake : snake.slice(0, snake.length-1);
    if (body.some(s => s.x===head.x && s.y===head.y)){
      gameOver(); return;
    }

    snake.unshift(head);

    if (willEat){
      score += POINTS;
      stepMs = Math.max(MIN_MS, stepMs - SPEEDUP);
      spawnBurst((food.x+0.5)*cell, (food.y+0.5)*cell, '#ffc24b');
      food = randFood();
      bumpScore();
      if (score > best){
        best = score;
        localStorage.setItem('snake_best', String(best));
        bestEl.textContent = best;
      }
    } else {
      snake.pop();
    }
    updateHud();
  }

  // ---------- State transitions ----------
  function start(){
    if (state === 'running') return;
    if (state === 'ready' || state === 'over') reset();
    state = 'running';
    hideOverlay();
    startLabel.textContent = '暂停';
    startBtn.querySelector('.ic').textContent = '❚❚';
    dpadCenter.textContent = '❚❚';
  }
  function pause(){
    if (state !== 'running') return;
    state = 'paused';
    showOverlay('PAUSED','已暂停','按 空格 或 点击按钮继续', '继续游戏', '▶');
    startLabel.textContent = '继续';
    startBtn.querySelector('.ic').textContent = '▶';
    dpadCenter.textContent = '▶';
  }
  function toggle(){
    if (state === 'running') pause();
    else start();
  }
  function restart(){
    reset();
    state = 'running';
    hideOverlay();
    startLabel.textContent = '暂停';
    startBtn.querySelector('.ic').textContent = '❚❚';
    dpadCenter.textContent = '❚❚';
  }
  function gameOver(){
    state = 'over';
    shake = 1;
    spawnBurst((snake[0].x+0.5)*cell, (snake[0].y+0.5)*cell, '#ff6b57');
    const isBest = score >= best && score > 0;
    showOverlay('GAME OVER','游戏结束',
      '本局得分 <b>'+score+'</b> · 长度 <b>'+snake.length+'</b>',
      '再来一局', '↻', isBest);
    startLabel.textContent = '重新开始';
    startBtn.querySelector('.ic').textContent = '↻';
    dpadCenter.textContent = '↻';
  }

  // ---------- Overlay ----------
  function showOverlay(tag, title, sub, btnText, icon, isBest){
    ovTag.textContent = tag;
    ovTitle.textContent = title;
    ovTitle.className = 'big' + (tag==='GAME OVER' ? ' coral' : '');
    ovSub.innerHTML = sub;
    ovBtn.innerHTML = '<span class="ic">'+icon+'</span>'+btnText;
    newBest.classList.toggle('show', !!isBest);
    overlay.classList.add('show');
  }
  function hideOverlay(){ overlay.classList.remove('show'); }

  // ---------- Input ----------
  function setDir(x,y){
    // prevent reversing into self
    if (x === -dir.x && y === -dir.y) return;
    nextDir = {x, y};
  }
  const DIRS = {
    up:{x:0,y:-1}, down:{x:0,y:1}, left:{x:-1,y:0}, right:{x:1,y:0}
  };

  window.addEventListener('keydown', function(e){
    const k = e.key;
    if (k==='ArrowUp' || k==='w' || k==='W'){ e.preventDefault(); if(state==='ready'||state==='over') start(); setDir(0,-1); }
    else if (k==='ArrowDown' || k==='s' || k==='S'){ e.preventDefault(); if(state==='ready'||state==='over') start(); setDir(0,1); }
    else if (k==='ArrowLeft' || k==='a' || k==='A'){ e.preventDefault(); if(state==='ready'||state==='over') start(); setDir(-1,0); }
    else if (k==='ArrowRight' || k==='d' || k==='D'){ e.preventDefault(); if(state==='ready'||state==='over') start(); setDir(1,0); }
    else if (k===' '){ e.preventDefault(); toggle(); }
    else if (k==='r' || k==='R'){ e.preventDefault(); restart(); }
  });

  startBtn.addEventListener('click', function(){
    if (state === 'running') pause();
    else if (state === 'paused') start();
    else restart();
  });
  restartBtn.addEventListener('click', restart);
  ovBtn.addEventListener('click', function(){
    if (state === 'over') restart();
    else start();
  });
  dpadCenter.addEventListener('click', function(){
    if (state === 'running') pause();
    else if (state === 'paused') start();
    else restart();
  });
  dpad.querySelectorAll('[data-dir]').forEach(function(b){
    const handler = function(e){
      e.preventDefault();
      const d = DIRS[b.dataset.dir];
      if (state === 'ready' || state === 'over') start();
      setDir(d.x, d.y);
    };
    b.addEventListener('pointerdown', handler);
  });

  // ---------- Rendering ----------
  function roundRect(x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y);
    ctx.arcTo(x+w,y,x+w,y+h,r);
    ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r);
    ctx.arcTo(x,y,x+w,y,r);
    ctx.closePath();
  }

  function draw(){
    const W = canvas.width/dpr, H = canvas.height/dpr;
    ctx.clearRect(0,0,W,H);

    // shake offset
    let ox=0, oy=0;
    if (shake > 0){
      ox = (Math.random()-0.5)*shake*8;
      oy = (Math.random()-0.5)*shake*8;
    }
    ctx.save();
    ctx.translate(ox,oy);

    // board background
    ctx.fillStyle = '#061a13';
    ctx.fillRect(0,0,W,H);

    // subtle checker
    for (let y=0;y<ROWS;y++){
      for (let x=0;x<COLS;x++){
        if ((x+y)%2===0){
          ctx.fillStyle = 'rgba(120,255,190,0.025)';
          ctx.fillRect(x*cell, y*cell, cell, cell);
        }
      }
    }
    // grid lines
    ctx.strokeStyle = 'rgba(120,255,190,0.05)';
    ctx.lineWidth = 1;
    for (let i=1;i<COLS;i++){
      ctx.beginPath(); ctx.moveTo(i*cell,0); ctx.lineTo(i*cell,H); ctx.stroke();
    }
    for (let i=1;i<ROWS;i++){
      ctx.beginPath(); ctx.moveTo(0,i*cell); ctx.lineTo(W,i*cell); ctx.stroke();
    }

    // food
    const fx = (food.x+0.5)*cell, fy = (food.y+0.5)*cell;
    const fr = cell*0.32 * (1 + Math.sin(foodPulse)*0.12);
    const glow = ctx.createRadialGradient(fx,fy,0,fx,fy,fr*2.4);
    glow.addColorStop(0,'rgba(255,194,75,0.55)');
    glow.addColorStop(1,'rgba(255,194,75,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(fx,fy,fr*2.4,0,Math.PI*2); ctx.fill();
    const fg = ctx.createRadialGradient(fx-fr*0.3,fy-fr*0.3,fr*0.1,fx,fy,fr);
    fg.addColorStop(0,'#ffe08a');
    fg.addColorStop(1,'#ff8a3d');
    ctx.fillStyle = fg;
    ctx.beginPath(); ctx.arc(fx,fy,fr,0,Math.PI*2); ctx.fill();
    // leaf
    ctx.fillStyle = '#8fe000';
    ctx.beginPath();
    ctx.ellipse(fx+fr*0.35, fy-fr*0.9, fr*0.35, fr*0.18, -0.6, 0, Math.PI*2);
    ctx.fill();

    // snake
    const n = snake.length;
    for (let i=n-1;i>=0;i--){
      const s = snake[i];
      const t = n>1 ? i/(n-1) : 0;
      const pad = cell*0.08;
      const x = s.x*cell+pad, y = s.y*cell+pad, sz = cell-pad*2;
      const r = cell*0.32;
      // color gradient head->tail
      const g = ctx.createLinearGradient(x,y,x,y+sz);
      if (i===0){
        g.addColorStop(0,'#e6ff8a');
        g.addColorStop(1,'#a6e000');
      } else {
        const l = 1 - t*0.55;
        g.addColorStop(0, 'rgb('+(150*l+40)+','+(220*l+30)+','+(60*l+20)+')');
        g.addColorStop(1, 'rgb('+(90*l+20)+','+(160*l+20)+','+(40*l+15)+')');
      }
      ctx.fillStyle = g;
      roundRect(x,y,sz,sz,r);
      ctx.fill();
      // subtle top highlight
      ctx.fillStyle = 'rgba(255,255,255,0.10)';
      roundRect(x+sz*0.12, y+sz*0.1, sz*0.76, sz*0.28, r*0.6);
      ctx.fill();
    }

    // head eyes
    const h = snake[0];
    const hx = (h.x+0.5)*cell, hy = (h.y+0.5)*cell;
    const ex = dir.x, ey = dir.y;
    const perpX = -ey, perpY = ex;
    const eo = cell*0.16, fo = cell*0.14;
    const eyeR = cell*0.11;
    for (const sgn of [1,-1]){
      const cx = hx + ex*fo + perpX*eo*sgn;
      const cy = hy + ey*fo + perpY*eo*sgn;
      ctx.fillStyle = '#04140f';
      ctx.beginPath(); ctx.arc(cx,cy,eyeR,0,Math.PI*2); ctx.fill();
      ctx.fillStyle = '#eafff4';
      ctx.beginPath(); ctx.arc(cx+ex*eyeR*0.3, cy+ey*eyeR*0.3, eyeR*0.4,0,Math.PI*2); ctx.fill();
    }

    // particles
    for (const p of particles){
      ctx.globalAlpha = Math.max(0, p.life);
      ctx.fillStyle = p.color;
      ctx.beginPath(); ctx.arc(p.x,p.y,p.size,0,Math.PI*2); ctx.fill();
    }
    ctx.globalAlpha = 1;

    ctx.restore();
  }

  // ---------- Loop ----------
  function loop(ts){
    if (last === undefined) last = ts;
    let dt = (ts - last)/1000;
    last = ts;
    if (dt > 0.1) dt = 0.1;

    foodPulse += dt*4;
    if (shake > 0) shake = Math.max(0, shake - dt*3);
    updateParticles(dt);

    if (state === 'running'){
      acc += dt*1000;
      let guard = 0;
      while (acc >= stepMs && guard < 5){
        acc -= stepMs;
        step();
        guard++;
        if (state !== 'running') break;
      }
    }

    draw();
    requestAnimationFrame(loop);
  }

  // ---------- Init ----------
  function init(){
    resize();
    reset();
    showOverlay('READY','贪吃蛇','用方向键控制，吃掉食物变长。<br>别撞墙，也别咬到自己！','开始游戏','▶');
    requestAnimationFrame(loop);
  }
  // ensure canvas has size before first draw
  requestAnimationFrame(function(){ init(); });
})();
</script>
